import React, { useState, useEffect } from 'react';
import axios from 'axios';
import ResetPasswordModal from './ResetPasswordModal';

export default function TeacherDashboard({ userName, handleLogout }) {
  const [myClasses, setMyClasses] = useState([]);
  const [showResetModal, setShowResetModal] = useState(false);

  useEffect(() => {
    // සර්වර් එකෙන් ඔක්කොම පන්ති ගෙනත්, මේ ලොග් වෙලා ඉන්න ටීචර්ගේ පන්ති විතරක් වෙන් කරගන්නවා
    axios.get('http://localhost:8081/api/timetable')
      .then(res => {
        if (res.data) {
            const filteredClasses = res.data.filter(cls => cls.teacher === userName);
            setMyClasses(filteredClasses);
        }
      })
      .catch(err => console.error(err));
  }, [userName]);

  return (
    <div style={{ padding: '40px', backgroundColor: '#f8fafc', minHeight: '100vh', fontFamily: 'sans-serif' }}>
      
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px' }}>
        <div>
            <h1 style={{ color: '#15803d', margin: 0 }}>Welcome, {userName}! 👨‍🏫</h1>
            <p style={{ color: '#64748b', marginTop: '5px' }}>Here are your assigned classes.</p>
        </div>
        <div>
            <button onClick={() => setShowResetModal(true)} style={{ padding: '10px 15px', marginRight: '10px', background: '#3b82f6', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>Change Password</button>
            <button onClick={handleLogout} style={{ padding: '10px 15px', background: '#ef4444', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>Logout</button>
        </div>
      </div>

      <div style={{ backgroundColor: 'white', borderRadius: '12px', padding: '20px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' }}>
        <h3 style={{ borderBottom: '2px solid #e2e8f0', paddingBottom: '10px', color: '#334155' }}>My Teaching Schedule</h3>
        
        {myClasses.length > 0 ? (
            <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', marginTop: '15px' }}>
              <thead>
                <tr style={{ backgroundColor: '#f1f5f9', color: '#475569', fontSize: '14px' }}>
                  <th style={{ padding: '12px' }}>Day</th>
                  <th style={{ padding: '12px' }}>Grade</th>
                  <th style={{ padding: '12px' }}>Subject</th>
                  <th style={{ padding: '12px' }}>Time</th>
                </tr>
              </thead>
              <tbody>
                {myClasses.map((cls, index) => (
                  <tr key={index} style={{ borderBottom: '1px solid #f1f5f9' }}>
                    <td style={{ padding: '12px', fontWeight: 'bold' }}>{cls.day}</td>
                    <td style={{ padding: '12px' }}>{cls.grade}</td>
                    <td style={{ padding: '12px' }}>{cls.subject}</td>
                    <td style={{ padding: '12px', color: '#15803d', fontWeight: 'bold' }}>{cls.time_slot}</td>
                  </tr>
                ))}
              </tbody>
            </table>
        ) : (
            <p style={{ color: '#ef4444', fontWeight: 'bold' }}>No classes assigned to you yet.</p>
        )}
      </div>

      {showResetModal && <ResetPasswordModal userName={userName} setShowResetModal={setShowResetModal} />}
    </div>
  );
}
